INSERT INTO `pages` (`id`,`document_id`,`page_number`,`text`,`character_count`) VALUES (101,1,101,'tanamanyňyz kem däldir! — Kim borsuňyz? Derrew özüňizi tanadyň! – diýip, Mädoraz dypow hemle urdy. — Köp ýaňrasaňyz, ýeke oka tabşyraryn! — Ýok, sen meni ataýyn diýseňem atyp bilmersiň! — Atalyk özüne ynamly, gaty arkaýyn gepleýärdi. — Gulaly goňruň şu mahal nirede gizlenip ýatanyny kim bilýär? Ýeke men bilýän! Eger meni hem atyp dynsaň, kim ony saňa aýdar? Hiç kimem aýtmaz! Ýöne menem içimi boşatman, göwün solpymdan çykman, saňa gerekli zady aýdyp goýbär öýtme, hawwa! Zorluk etseň-ä, asylam aýtman! Gulalynyň kellesi üçin goýlan baýragy almagyň höwesindäki nökerleriň birnäçesi Mädoraz dypowa basalyk berip geplediler. — Degme, komandir! Isläniçe ýaňrasyn! Soňundan bize gerek zady aýtsa bolýar. — Batyr jigitler! Men ýaňramok-da, hakyky bolan işleri ýatlap durun. Ine, siziň şu komandiriňiz maňa din-yslama kast etmäni, metjit ýumurmany, atababalarymyzyň mazaryny depelemäni, arak-şerap içmäni, kesekiniň gelin-gyzyna göz gyzdyrmany, aý, garaz, nirede bir haramzadalyk bolsa, şony öwretdi.

